<script lang="ts">
 import type {Project} from "./model";import type {ReferenceKind} from "./catalog-definitions";import {referenceRows} from "./reference-catalogs";import {Search,FolderOpen,X} from "@lucide/svelte";import {translator} from "./i18n";
 export let project:Project;export let kind:ReferenceKind;export let value="";export let onopen:(kind:ReferenceKind)=>void;
 let open=false,query="",root:HTMLDivElement,rect={left:0,top:0,width:300};$:t=translator(project.settings.language);
 $:rows=referenceRows(project,kind).filter(r=>r.active&&(r.name+" "+r.code).toLocaleLowerCase().includes(query.toLocaleLowerCase()));
 function toggle(){open=!open;if(open){const r=root.getBoundingClientRect();rect={left:Math.max(8,Math.min(window.innerWidth-360,r.left)),top:Math.max(8,Math.min(window.innerHeight-300,r.bottom+4)),width:Math.max(320,Math.min(500,r.width))};}}
</script>
<svelte:window onpointerdown={e=>{if(open&&root&&!root.contains(e.target as Node))open=false;}} onkeydown={e=>{if(e.key==="Escape")open=false;}}/>
<div class="reference-picker" bind:this={root}><input bind:value/><button type="button" aria-label={t("Выбрать из справочника","Selectează din catalog")} aria-expanded={open} onclick={toggle}>…</button><button type="button" aria-label={t("Очистить значение","Șterge valoarea")} onclick={()=>value=""}><X size={15}/></button>
 {#if open}<div class="reference-popup" style:left={rect.left+"px"} style:top={rect.top+"px"} style:width={rect.width+"px"} role="dialog" aria-label={t("Выбор записи","Selectare înregistrare")}><label><Search size={16}/><input aria-label={t("Поиск в справочнике","Căutare în catalog")} bind:value={query}/></label><div role="listbox" aria-label={t("Записи справочника","Înregistrări catalog")}>{#each rows as row}<button type="button" role="option" aria-selected={value===(kind==="units"?row.attributes.symbol||row.name:row.name)} onclick={()=>{value=kind==="units"?row.attributes.symbol||row.name:row.name;open=false;}}>{row.name}<small>{row.code}</small></button>{/each}{#if !rows.length}<p>{t("Записи не найдены","Înregistrări negăsite")}</p>{/if}</div><button type="button" class="button secondary" onclick={()=>{open=false;onopen(kind);}}><FolderOpen size={16}/>{t("Сохранить и открыть справочник","Salvează și deschide catalogul")}</button></div>{/if}
</div>
<style>.reference-picker{display:flex;min-width:0;gap:0}.reference-picker>input{flex:1;min-width:0;width:100%}.reference-picker>button{display:flex;align-items:center;justify-content:center;flex:none;width:30px;border:1px solid var(--border);background:var(--input);color:var(--text);padding:0}.reference-popup{position:fixed;z-index:25000;box-shadow:0 8px 28px #0005;border:1px solid var(--border);background:var(--surface);padding:12px;display:flex;flex-direction:column;gap:12px}.reference-popup label{display:flex;gap:8px;align-items:center}.reference-popup label input{min-width:0;width:100%}.reference-popup [role="listbox"]{max-height:160px;overflow:auto}.reference-popup [role="option"]{display:flex;justify-content:space-between;gap:12px;width:100%;padding:9px;background:transparent;border:0;text-align:left;color:var(--text)}.reference-popup [role="option"]:hover{background:var(--hover)}.reference-popup small{color:var(--muted)}</style>
